class LimitError(Exception): pass

def withdraw(acc, amt):
    if amt > acc["bal"]:
        raise LimitError("余额不足")
    acc["bal"] -= amt

u = {"bal": 50}
try:
    withdraw(u, 80)
except LimitError as e:
    print(e, u["bal"])
